def find_minimum_time(strength: list[int], k: int) -> int:
    n = len(strength)
    full = (1 << n) - 1
    INF = float("inf")
    dp = [INF] * (1 << n)      # dp[mask] = least minutes to break the locks in mask
    dp[0] = 0
    for mask in range(1 << n):
