def minimum_moves(grid: list[list[int]]) -> int:
    n = len(grid)
    target = (n - 1, n - 2, 0)             # (row, col of the top left cell, orientation) 0 = horizontal
    seen = {(0, 0, 0)}
    queue = deque([(0, 0, 0, 0)])          # row, col, orientation, distance
    while queue:
        r, c, o, d = queue.popleft()
        if (r, c, o) == target:
            return d
        nxt = []
        if o == 0:                          # horizontal: cells (r, c) and (r, c + 1)
            if c + 2 < n and grid[r][c + 2] == 0:
                nxt.append((r, c + 1, 0))
            if r + 1 < n and grid[r + 1][c] == 0 and grid[r + 1][c + 1] == 0:
                nxt.append((r + 1, c, 0))   # move down
                nxt.append((r, c, 1))       # rotate clockwise
        else:                               # vertical: cells (r, c) and (r + 1, c)
            if r + 2 < n and grid[r + 2][c] == 0:
                nxt.append((r + 1, c, 1))
            if c + 1 < n and grid[r][c + 1] == 0 and grid[r + 1][c + 1] == 0:
                nxt.append((r, c + 1, 1))   # move right
                nxt.append((r, c, 0))       # rotate counterclockwise
        for state in nxt:
            if state not in seen:
                seen.add(state)
                queue.append(state + (d + 1,))
    return -1

def solve(nums: list[int], queries: list[list[int]]) -> list[int]:
    MOD = 10 ** 9 + 7
    n = len(nums)
    threshold = math.isqrt(n) + 1
    answers = [0] * len(queries)
    small = defaultdict(list)                 # y -> indices of queries with that small y
    for qi, (x, y) in enumerate(queries):
        if y < threshold:
            small[y].append(qi)
        else:
            answers[qi] = sum(nums[x::y]) % MOD   # at most n / y terms
    for y, group in small.items():
        suffix = [0] * (n + y)                # suffix[j] = nums[j] + nums[j + y] + ...
        for j in range(n - 1, -1, -1):
            suffix[j] = suffix[j + y] + nums[j]
        for qi in group:
            answers[qi] = suffix[queries[qi][0]] % MOD
    return answers

