def minimum_added_integer(nums1: list[int], nums2: list[int]) -> int:
    a = sorted(nums1)
    b = sorted(nums2)

    def works(x: int) -> bool:
        i = skipped = 0
        for v in b:
            while i < len(a) and a[i] + x != v:
                i += 1
                skipped += 1
                if skipped > 2:
                    return False
            if i == len(a):
                return False
            i += 1
        return True

