def minimum_cost(target: str, words: list[str], costs: list[int]) -> int:
    n = len(target)
    BASE = 911382323
    MOD = (1 << 61) - 1
    # cheapest cost for each distinct word
    cheapest = {}
    for w, c in zip(words, costs):
        if c < cheapest.get(w, float("inf")):
            cheapest[w] = c
    # one hash table per word length
    by_len = defaultdict(dict)
    for w, c in cheapest.items():
        h = 0
        for ch in w:
            h = (h * BASE + ord(ch)) % MOD
        by_len[len(w)][h] = c
    lengths = sorted(by_len)
    power = {L: pow(BASE, L, MOD) for L in lengths}
    prefix = [0] * (n + 1)
    for i, ch in enumerate(target):
        prefix[i + 1] = (prefix[i] * BASE + ord(ch)) % MOD
    INF = float("inf")
    dp = [INF] * (n + 1)
    dp[0] = 0
    for i in range(n):
        base_cost = dp[i]
        if base_cost == INF:
            continue
        hi = prefix[i]
        for L in lengths:
            j = i + L
            if j > n:
                break
            sub_hash = (prefix[j] - hi * power[L]) % MOD
            c = by_len[L].get(sub_hash)
            if c is not None and base_cost + c < dp[j]:
                dp[j] = base_cost + c
    return dp[n] if dp[n] < INF else -1

