def sum_of_largest_primes(s: str) -> int:
    """Enumerate all substrings, keep distinct primes, sum the three largest."""
    def is_prime(v: int) -> bool:
        if v < 2:
            return False
        if v % 2 == 0:
            return v == 2
        d = 3
        while d * d <= v:
            if v % d == 0:
                return False
            d += 2
        return True

    primes = set()
    n = len(s)
    for i in range(n):
        for j in range(i + 1, n + 1):
            v = int(s[i:j])
            if v not in primes and is_prime(v):
                primes.add(v)
    return sum(sorted(primes, reverse=True)[:3])

