def box_delivering(boxes: List[List[int]], ports_count: int, max_boxes: int, max_weight: int) -> int:
    """Linear DP with a sliding window minimum over feasible load starts."""
    n = len(boxes)
    chg = [0] * (n + 1)              # chg[k]: port changes among boxes[0..k-1]
    prefix_w = [0] * (n + 1)
    for i in range(n):
        prefix_w[i + 1] = prefix_w[i] + boxes[i][1]
        if i > 0:
            chg[i + 1] = chg[i] + (boxes[i][0] != boxes[i - 1][0])
    dp = [0] * (n + 1)
    window = deque([0])              # candidate starts j, increasing dp[j] - chg[j+1]
    for i in range(1, n + 1):
        while window and (i - window[0] > max_boxes or prefix_w[i] - prefix_w[window[0]] > max_weight):
            window.popleft()
        j = window[0]
        dp[i] = dp[j] - chg[j + 1] + chg[i] + 2
        if i < n:
            key = dp[i] - chg[i + 1]
            while window and dp[window[-1]] - chg[window[-1] + 1] >= key:
                window.pop()
            window.append(i)
    return dp[n]

