def find_indices(nums: List[int], index_difference: int, value_difference: int) -> List[int]:
    """Sweep j while tracking the min and max of the allowed prefix of i."""
    n = len(nums)
    lo = hi = -1                      # indices of the prefix minimum and maximum
    for j in range(index_difference, n):
        k = j - index_difference      # newest index allowed as a partner
        if lo < 0 or nums[k] < nums[lo]:
            lo = k
        if hi < 0 or nums[k] > nums[hi]:
            hi = k
        if nums[j] - nums[lo] >= value_difference:
            return [lo, j]
        if nums[hi] - nums[j] >= value_difference:
            return [hi, j]
    return [-1, -1]

def supersequences(words: List[str]) -> List[List[int]]:
    """Find the minimal sets of doubled letters whose complement induces an acyclic graph."""
    letters = sorted({c for w in words for c in w})
    index = {c: i for i, c in enumerate(letters)}
    k = len(letters)
    adj = [0] * k                      # adj[u]: bitmask of successors of u
    forced = 0                         # letters that must be doubled (words like "aa")
    for a, b in words:
        u, v = index[a], index[b]
        if u == v:
            forced |= 1 << u
        else:
            adj[u] |= 1 << v

    def acyclic(mask: int) -> bool:
        """True if the subgraph induced on the letters in mask has no cycle (sink removal)."""
        while mask:
            remaining = mask
            while remaining:
                low = remaining & -remaining
                u = low.bit_length() - 1
                if adj[u] & mask == 0:  # u is a sink in the induced subgraph
                    break
                remaining ^= low
            else:
                return False            # every vertex has an edge inside mask: a cycle exists
            mask ^= low
        return True

    free = [i for i in range(k) if not forced >> i & 1]
    full = (1 << k) - 1
    for size in range(len(free) + 1):
        found = []
        for combo in itertools.combinations(free, size):
            doubled = forced
            for i in combo:
                doubled |= 1 << i
            if acyclic(full ^ doubled):
                found.append(doubled)
        if found:
            result = []
            for doubled in found:
                row = [0] * 26
                for i, c in enumerate(letters):
                    row[ord(c) - 97] = 2 if doubled >> i & 1 else 1
                result.append(row)
            return result
    return []

