def maximum_number_of_ones(width: int, height: int, side_length: int, max_ones: int) -> int:
    """Choose the max_ones residue classes modulo side_length that cover the most cells."""
    s = side_length
    sizes = []
    for r in range(s):
        rows = (height - r + s - 1) // s      # cells with row index congruent to r
