def minimum_cost(start: List[int], target: List[int], special_roads: List[List[int]]) -> int:
    """Dijkstra over the start, target and road endpoints with Manhattan walking edges."""
    points = {tuple(start), tuple(target)}
    for x1, y1, x2, y2, _ in special_roads:
        points.add((x1, y1))
        points.add((x2, y2))
    nodes = list(points)
    index = {p: i for i, p in enumerate(nodes)}
    roads = [[] for _ in nodes]
    for x1, y1, x2, y2, cost in special_roads:
        roads[index[(x1, y1)]].append((index[(x2, y2)], cost))

    src, dst = index[tuple(start)], index[tuple(target)]
    dist = [math.inf] * len(nodes)
    dist[src] = 0
    heap = [(0, src)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        if u == dst:
            break
        ux, uy = nodes[u]
        for v, (vx, vy) in enumerate(nodes):          # walking edges
            nd = d + abs(ux - vx) + abs(uy - vy)
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
        for v, cost in roads[u]:                      # special roads
            nd = d + cost
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return dist[dst]

