def get_smallest_string(s: str, k: int) -> str:
    out = []
    for ch in s:
        offset = ord(ch) - ord("a")
        cost_to_a = min(offset, 26 - offset)  # shorter way around the circle
        if cost_to_a <= k:
            out.append("a")
