def distinct_sequences(n: int) -> int:
    MOD = 10**9 + 7
    if n == 1:
        return 6
    from math import gcd
    # every valid ordered pair (previous, last) is a state
    states = [(a, b) for a in range(1, 7) for b in range(1, 7) if a != b and gcd(a, b) == 1]
    index = {s: i for i, s in enumerate(states)}
    # preds[j] = states that may move into state j by one more roll
    preds = [[] for _ in states]
    for i, (a, b) in enumerate(states):
        for c in range(1, 7):
            if c != a and c != b and gcd(b, c) == 1:
                preds[index[(b, c)]].append(i)
    counts = [1] * len(states)  # sequences of length 2
    for _ in range(n - 2):
        counts = [sum([counts[i] for i in p]) % MOD for p in preds]
    return sum(counts) % MOD

def count_of_peaks(nums: list[int], queries: list[list[int]]) -> list[int]:
    n = len(nums)
    nums = nums[:]
    tree = [0] * (n + 1)  # Fenwick tree over peak flags, 1 indexed

    def add(i, delta):
        i += 1
        while i <= n:
            tree[i] += delta
            i += i & -i

    def prefix(i):  # sum of flags at indices 0..i-1
        total = 0
        while i > 0:
            total += tree[i]
            i -= i & -i
        return total

    def is_peak(i):
        return 0 < i < n - 1 and nums[i] > nums[i - 1] and nums[i] > nums[i + 1]

    flag = [0] * n
    for i in range(1, n - 1):
        if is_peak(i):
            flag[i] = 1
            add(i, 1)

    answers = []
    for kind, a, b in queries:
        if kind == 1:
            # interior of nums[a..b] is a+1 .. b-1
            answers.append(prefix(b) - prefix(a + 1) if b - a >= 2 else 0)
        else:
            nums[a] = b
            for i in (a - 1, a, a + 1):
                if 0 < i < n - 1:
                    new = 1 if is_peak(i) else 0
                    if new != flag[i]:
                        add(i, new - flag[i])
                        flag[i] = new
    return answers

