def component_value(nums: list[int], edges: list[list[int]]) -> int:
    n = len(nums)
    total = sum(nums)
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    # BFS from node 0 gives a parent array and an order; reversed order is bottom up
    parent = [-1] * n
    order = [0]
    seen = [False] * n
    seen[0] = True
    for v in order:
        for w in adj[v]:
            if not seen[w]:
                seen[w] = True
                parent[w] = v
                order.append(w)
    bottom_up = order[::-1]
    biggest = max(nums)

    def can_split(target):
        rest = nums[:]  # sum of the part of each subtree not yet cut away
        for v in bottom_up:
            if rest[v] > target:
                return False
            if rest[v] == target:
                rest[v] = 0  # detach this piece as its own component
            elif parent[v] == -1:
                return False  # root left with a partial component
            if parent[v] != -1:
                rest[parent[v]] += rest[v]
        return True

    for k in range(min(n, total // biggest), 0, -1):
        if total % k == 0 and can_split(total // k):
            return k - 1
    return 0

def min_distance(height: int, width: int, tree: list[int], squirrel: list[int], nuts: list[list[int]]) -> int:
    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    total = 0
    best_change = float("inf")  # saving (or cost) from picking this nut first
    for nut in nuts:
        to_tree = dist(nut, tree)
        total += 2 * to_tree
        best_change = min(best_change, dist(squirrel, nut) - to_tree)
    return total + best_change

def smallest_factorization(num: int) -> int:
    if num < 10:
        return num  # a single digit is already optimal (1 maps to 1)
    digits = []
    for d in range(9, 1, -1):
        while num % d == 0:
            digits.append(d)
            num //= d
    if num != 1:
        return 0  # a prime factor larger than 7 remains
    x = 0
    for d in reversed(digits):  # smallest digits first
        x = x * 10 + d
    return x if x <= 2**31 - 1 else 0
